DROP TABLE IF EXISTS `item`;
CREATE TABLE IF NOT EXISTS `item` (
  `itemId` int(11) NOT NULL,
  `name` text NOT NULL,
  `description` text NOT NULL,
  `type` smallint(6) NOT NULL DEFAULT 0,
  `iconPath` varchar(200) DEFAULT NULL,
  `frameImgPath` varchar(200) DEFAULT NULL,
  `gender` tinyint(4) NOT NULL DEFAULT -1,
  `isStackable` tinyint(1) NOT NULL DEFAULT 1,
  `itemOption` text DEFAULT NULL,
  `itemOptionValue` text DEFAULT NULL,
  `giftData` text DEFAULT NULL,
  `atkRange` varchar(1000) DEFAULT NULL,
  `defRange` varchar(1000) DEFAULT NULL,
  `hpRange` varchar(1000) DEFAULT NULL,
  `mpRange` varchar(1000) DEFAULT NULL,
  `requireStr` int(11) NOT NULL DEFAULT 0,
  `requireInt` int(11) NOT NULL DEFAULT 0,
  `requireAgi` int(11) NOT NULL DEFAULT 0,
  `expire` bigint(20) DEFAULT NULL,
  `isOnSky` tinyint(1) NOT NULL DEFAULT 0,
  `canTrade` tinyint(1) NOT NULL DEFAULT 1,
  `petNClass` tinyint(4) NOT NULL DEFAULT -1,
  `element` tinyint(4) NOT NULL DEFAULT -1,
  `price` int(11) NOT NULL DEFAULT 10,
  `wingFrameNum` tinyint(4) NOT NULL DEFAULT 2,
  `skinFrameNum` tinyint(4) NOT NULL DEFAULT 2,
  PRIMARY KEY (`itemId`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

