-- 
-- Definition of hidden_stat
-- 

DROP TABLE IF EXISTS `hidden_stat`;
CREATE TABLE IF NOT EXISTS `hidden_stat` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `IdWeapon` int(11) DEFAULT NULL,
  `IdHat` int(11) DEFAULT NULL,
  `IdArmour` int(11) DEFAULT NULL,
  `IdShoe` int(11) DEFAULT NULL,
  `IdGlove` int(11) DEFAULT NULL,
  `Data` varchar(2048) NOT NULL DEFAULT '[]',
  `Comment` varchar(1024) NOT NULL,
  PRIMARY KEY (`Id`) USING BTREE,
  UNIQUE KEY `IdWeapon` (`IdWeapon`,`IdHat`,`IdArmour`,`IdShoe`,`IdGlove`) USING BTREE,
  KEY `IdWeapon_2` (`IdWeapon`) USING BTREE,
  KEY `IdHat` (`IdHat`) USING BTREE,
  KEY `IdArmour` (`IdArmour`) USING BTREE,
  KEY `IdShoe` (`IdShoe`) USING BTREE,
  KEY `IdGlove` (`IdGlove`) USING BTREE,
  CONSTRAINT `hidden_stat_ibfk_1` FOREIGN KEY (`IdArmour`) REFERENCES `item` (`itemId`),
  CONSTRAINT `hidden_stat_ibfk_2` FOREIGN KEY (`IdGlove`) REFERENCES `item` (`itemId`),
  CONSTRAINT `hidden_stat_ibfk_3` FOREIGN KEY (`IdHat`) REFERENCES `item` (`itemId`),
  CONSTRAINT `hidden_stat_ibfk_4` FOREIGN KEY (`IdShoe`) REFERENCES `item` (`itemId`),
  CONSTRAINT `hidden_stat_ibfk_5` FOREIGN KEY (`IdWeapon`) REFERENCES `item` (`itemId`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

