-- 
-- Definition of iteminfo
-- 

DROP TABLE IF EXISTS `iteminfo`;
CREATE TABLE IF NOT EXISTS `iteminfo` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(1000) NOT NULL COMMENT 'Tên',
  `isPercent` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Là chỉ số %',
  UNIQUE KEY `ID` (`ID`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;

