INSERT INTO `npc`(`npcId`,`name`,`chat`,`optionName`,`optionId`,`x`,`y`,`imgPath`,`type`,`bounds`) VALUES(-43,'Chú Cuội','[\"Ghé qua chế tạo hộp bánh trung thu nhé!\"]','[\"Chế tạo hộp bánh trung thu thường\",\"Chế tạo hộp bánh trung thu VIP\",\"Top dùng hộp bánh trung thu thường\",\"Top dùng hộp bánh trung thu VIP\",\"Hướng dẫn sự kiện\",\"Nhận quà mốc hộp thường\",\"Nhận quà mốc hộp VIP\"]','[105,106,107,108,109,110,111]',202,268,'npcs/axgru.png',1,'[-25,-25,50,50]'),(-42,'Thợ Săn Boss','[\"Săn boss nhận Hoa Ngọc!\",\"Đổi Hoa Ngọc lấy quà tại đây\"]','[\"Đổi Hoa Ngọc\",\"Xem top săn boss\",\"Xem top số dư Hoa Ngọc\",\"Đổi hộp quà\"]','[101,102,103,104]',202,268,'npcs\\luno.png',1,'[-25,-25,50,50]'),(-41,'BANH SINH NHAT','[]','[\"Làm bánh tét\",\"Làm bánh chưng\",\"Bảng xếp hạng ăn bánh tét\",\"Bảng xếp hạng ăn bánh chưng\",\"Hướng dẫn sự kiện\", \"Đổi quà\", \"Nhận mốc quà\", \"Bảng xếp hạng sử dụng hộp quà\"]','[90,91,92,93,94,95,96,97]',202,268,'npcs/banhsn.png',1,'[-25,-25,50,50]'),(-40,'WINDY','[]','[]','[]',133,466,'npcs/Su gia bang hoi.png',1,'[-25,-25,50,50]'),(-39,'GIAN THUONG','[\"Mua đồ theo giá sàn đây\"]','[\"Shop gian thương\",\"Bán vật phẩm\"]','[78,79]',486,267,'npcs/gian_thuong.png',1,'[-25,-25,50,50]'),(-38,'BAC SI THIEN THAN','[]','[]','[]',566,419,'npcs/bac_si.png',1,'[-25,-25,50,50]'),(-37,'DU CON THIEN THAN','[]','[]','[]',642,461,'npcs/du_con_2nd.png',1,'[-25,-25,50,50]'),(-36,'KE THU THAP','[]','[]','[]',346,197,'npcs/ke_thu_thap.png',1,'[-25,-25,50,50]'),(-35,'QUAN LY THIEN THAN','[]','[]','[]',385,266,'npcs/quan_ly.png',1,'[-25,-25,50,50]'),(-34,'AC','[]','[]','[]',377,362,'npcs/Su gia bang hoi.png',1,'[-25,-25,50,50]'),(-33,'SHOP THIEN DINH','[]','[]','[]',477,250,'npcs/Thu-Ban.png',1,'[-25,-25,50,50]'),(-32,'THO REN','[]','[]','[]',173,162,'npcs/Tho_Ren.png',1,'[-25,-25,50,50]'),(-31,'NGUOI GIU CONG','[]','[]','[]',297,122,'npcs/Le-Tan.png',1,'[-25,-25,50,50]'),(-30,'BANG XEP HANG','[]','[]','[]',321,234,'npcs/huong_dan_choi.png',1,'[-25,-25,50,50]'),(-29,'TONG QUAN THIEN DINH','[]','[]','[]',105,122,'npcs/tong_quan_thien_than.png',1,'[-25,-25,50,50]'),(-28,'DAU TRUONG','[\"Đấu trường sôi động\"]','[\"Pet League Beta\",\"Chọn pet phòng thủ\",\"Vượt ải\",\"Shop đấu trường\",\"Shop đấu trường sinh tử\",\"Thách đấu\",\"Mua bình năng lượng\",\"Top điểm tích lũy\",\"Báo danh đấu trường\",\"Top vượt ải\"]','[64,65,10,11,12,13,14,63,67,80]',533,474,'npcs/arena.png',1,'[-25,-25,50,50]'),(-27,'DAI TIEN NU','[]','[]','[]',469,162,'npcs/dai_tien_nu.png',1,'[-25,-25,50,50]'),(-26,'SU GIA BANG HOI','[\"Xin chào! Tôi là NPC của bang hội, tôi có thể giúp bạn nhận và trả nhiệm vụ của bang hội.\",\"Chào bạn! Cùng tôi vào khu vực bang để khám phá những hoạt động và sự kiện đặc biệt dành cho thành viên của bang hội.\",\"Bạn có muốn biết xem ai là người mạnh nhất trong bang? Hãy xem bảng sếp hạng cấp bậc bang hội để biết thêm chi tiết.\",\"Nếu bạn muốn tạo một bang hội riêng, hãy đến gặp tôi. Tôi sẽ hướng dẫn bạn qua quy trình để tạo một bang hội.\",\"Đừng bỏ lỡ các sự kiện bang hội! Chúng mang đến những thử thách hấp dẫn và phần thưởng đặc biệt cho thành viên của bang.\",\"Cống hiến cho bang hội là cách bạn góp phần vào sự phát triển của bang. Hãy đến gặp tôi để biết thêm về cách cống hiến cho bang hội.\",\"Hãy tận hưởng những nhiệm vụ bang hội mà chúng tôi cung cấp. Chúng không chỉ giúp bạn kiếm thêm phần thưởng mà còn gắn kết thành viên trong bang.\",\"Đến khu vực bang để gặp những người chơi đồng đội, trao đổi kinh nghiệm và chiến lược. Đó là nơi tuyệt nhất để tăng sức mạnh của bang hội.\",\"Nếu bạn muốn xem ai đang dẫn đầu bang hội, hãy xem bảng sếp hạng cấp bậc. Bạn có thể cạnh tranh và leo lên vị trí cao hơn!\",\"Tạo một bang hội của riêng bạn là cách tuyệt vời để gặp gỡ và kết nối với những người chơi khác. Hãy đến gặp tôi để biết thêm chi tiết về cách tạo bang hội.\"]','[\"Vào khu vực bang\",\"Top lvl bang hội\",\"Tạo bang hội\",\"Sự kiện bang hội\",\"Cống hiến bang hội\"]','[44,45,46,47,48]',409,402,'npcs/Su gia bang hoi.png',1,'[-25,-25,50,50]'),(-25,'SU GIA THIEN THAN','[]','[\"Hướng dẫn lên thiên đình\", \"Hiến tặng thú cưng\"]','[88,89]',322,332,'npcs\\\\su_gia_thien_than.png',1,'[-25,-25,50,50]'),(-24,'ÔNG GIÀ NOEL','[]','[\"Điểm danh\",\"Nhận quà mốc nạp\",\"Top tổng nạp\"]','[87,99,100]',226,396,'npcs\\\\giaNoel.png',1,'[-25,-25,50,50]'),(-23,'HUONG DAN','[]','[]','[]',250,292,'npcs\\\\huong_dan choi.png',1,'[-25,-25,50,50]'),(-22,'GIAN THUONG','[\"Mua đồ theo giá sàn đây\"]','[\"Shop gian thương\",\"Bán vật phẩm\"]','[78,79]',663,233,'npcs/gian_thuong.png',1,'[-25,-25,50,50]'),(-21,'TRE CON','[\"Chúng tôi KHÔNG hỏi anh ấy nơi cất giấu kho báu!!! Chúng tôi thậm chí không hỏi anh ta liệu có kho báu nào hay không!! Tôi không chắc, nhưng… …tất cả mọi người đều ra khơi, mạo hiểm mạng sống của mình để tìm kiếm nó!!! Nếu bạn hỏi ông già này bất cứ điều gì về nó ở đây và ngay bây giờ... Thì tôi sẽ thôi làm cướp biển! Tôi không muốn tham gia vào một cuộc phiêu lưu nhàm chán như thế đâu!”\",\"“Bạn đã đến mà không sợ hãi. Đừng có bất kỳ hối tiếc, bất kể điều gì xảy ra. Đây là cuộc đấu tay đôi mà bạn muốn.”\",\"“Nếu bạn không chấp nhận rủi ro, bạn không thể tạo ra tương lai.”\",\"“Tôi có tham vọng của tôi, bạn cũng có tham vọng của bạn. Điều đó có nghĩa là bạn chỉ nên tiếp tục tiến tới mục tiêu đó.”\",\"“Một hòn đảo từ một giấc mơ trong một giấc mơ? Tôi không bao giờ có thể bỏ qua một cuộc phiêu lưu tuyệt vời như thế này!”\",\"“Ở một mình còn đau hơn cả nỗi đau.”\",\"“Anh hùng? KHÔNG! Chúng tôi là cướp biển! Tôi yêu anh hùng, nhưng tôi không muốn trở thành anh hùng! Bạn có biết anh hùng là gì không? Nói rằng có một miếng thịt. Cướp biển sẽ mở tiệc và ăn nó, nhưng các anh hùng sẽ chia sẻ nó với những người khác. Tôi muốn tất cả thịt!”\",\"“Chúng ta có phải là bạn không? Hay chúng ta là kẻ thù? Đó là những điều bạn quyết định cho chính mình!”\",\"“Sự lãng quên giống như một vết thương. Vết thương có thể lành nhưng nó đã để lại sẹo.”\",\"“Nếu tôi được tái sinh… tôi muốn trở thành một con ngao.”\"]','[\"Làm diều giấy\",\"Làm diều vải\",\"Top diều giấy\",\"Top diều vải\",\"Hướng dẫn\"]','[72, 73, 74, 75, 76]\n',105,563,'npcs/luffy.png',1,'[-25,-25,50,50]'),(-20,'BAC HOC DAU GAU','[\"Nơi nhận nhiệm vụ\"]','[\"Số nhiệm vụ đã hoàn thành\"]','[61]',106,253,'npcs\\bac_hoc_dau_gau.png',1,'[-25,-25,50,50]'),(-19,'Nhà nghiên cứu','[]','[]','[]',506,349,'dialog/empty.png',0,'[-25,-25,50,50]'),(-18,'Kĩ năng bang hội','[]','[\"Cộng tiềm năng\", \"Tẩy tiềm năng\", \"Nâng cấp\"]','[52,53,54]',130,225,'dialog/empty.png',0,'[-25,-25,50,50]'),(-17,'Nhà chính bang hội','[]','[\"Duyệt thành viên\",\"Nâng cấp\",\"Phong tước\",\"Thay đổi khẩu hiệu\",\"Rời bang\"]','[51,55,56,57,58]',338,125,'dialog/empty.png',0,'[-25,-25,50,50]'),(-16,'Shop bảo vật bang hội','[]','[\"Shop bang hội\", \"Nâng cấp\"]','[49, 50]',178,141,'dialog/empty.png',0,'[-25,-25,50,50]'),(-15,'SU GIA BANG HOI','[\"Xin chào! Tôi là NPC của bang hội, tôi có thể giúp bạn nhận và trả nhiệm vụ của bang hội.\",\"Chào bạn! Cùng tôi vào khu vực bang để khám phá những hoạt động và sự kiện đặc biệt dành cho thành viên của bang hội.\",\"Bạn có muốn biết xem ai là người mạnh nhất trong bang? Hãy xem bảng sếp hạng cấp bậc bang hội để biết thêm chi tiết.\",\"Nếu bạn muốn tạo một bang hội riêng, hãy đến gặp tôi. Tôi sẽ hướng dẫn bạn qua quy trình để tạo một bang hội.\",\"Đừng bỏ lỡ các sự kiện bang hội! Chúng mang đến những thử thách hấp dẫn và phần thưởng đặc biệt cho thành viên của bang.\",\"Cống hiến cho bang hội là cách bạn góp phần vào sự phát triển của bang. Hãy đến gặp tôi để biết thêm về cách cống hiến cho bang hội.\",\"Hãy tận hưởng những nhiệm vụ bang hội mà chúng tôi cung cấp. Chúng không chỉ giúp bạn kiếm thêm phần thưởng mà còn gắn kết thành viên trong bang.\",\"Đến khu vực bang để gặp những người chơi đồng đội, trao đổi kinh nghiệm và chiến lược. Đó là nơi tuyệt nhất để tăng sức mạnh của bang hội.\",\"Nếu bạn muốn xem ai đang dẫn đầu bang hội, hãy xem bảng sếp hạng cấp bậc. Bạn có thể cạnh tranh và leo lên vị trí cao hơn!\",\"Tạo một bang hội của riêng bạn là cách tuyệt vời để gặp gỡ và kết nối với những người chơi khác. Hãy đến gặp tôi để biết thêm chi tiết về cách tạo bang hội.\"]','[\"Vào khu vực bang\",\"Top lvl bang hội\",\"Tạo bang hội\",\"Sự kiện bang hội\",\"Cống hiến bang hội\"]','[44,45,46,47,48]',326,236,'npcs/Su gia bang hoi.png',1,'[-25,-25,50,50]'),(-14,'Ki ốt linh tinh','[]','[\"Mua đồ\", \"Gian hàng của tôi\"]','[39,40]',496,247,'dialog/empty.png',1,'[-25,-25,50,50]'),(-13,'Ki ốt thú cưng','[]','[\"Mua đồ\", \"Gian hàng của tôi\"]','[37,38]',656,115,'dialog/empty.png',1,'[-25,-25,50,50]'),(-12,'Ki ốt ngọc','[]','[\"Mua đồ\", \"Gian hàng của tôi\"]','[35,36]',320,186,'dialog/empty.png',1,'[-25,-25,50,50]'),(-11,'Ki ốt giáp','[]','[\"Mua đồ\", \"Gian hàng của tôi\"]','[33,34]',113,222,'dialog/empty.png',1,'[-25,-25,50,50]'),(-10,'Ki ốt vũ khí','[]','[\"Mua đồ\", \"Gian hàng của tôi\"]','[31,32]',288,101,'dialog/empty.png',1,'[-25,-25,50,50]'),(-9,'Ki ốt mũ','[]','[\"Mua đồ\", \"Gian hàng của tôi\"]','[29,30]',106,113,'dialog/empty.png',1,'[-25,-25,50,50]'),(-8,'DAI CHIEN THAN','[\"Hãy chuẩn bị cho cuộc chiến! Chúng ta sẽ đánh bại kẻ thù cùng nhau!\",             \"Tôi đã huấn luyện các chiến binh tốt nhất để giúp chúng ta chiến thắng!\",             \"Chúng ta không thể lùi bước! Sự tồn tại của toàn bộ thành phố đang phụ thuộc vào chúng ta!\",             \"Không có gì có thể ngăn được quyết tâm của chúng ta trong cuộc chiến này!\",             \"Hãy tin tưởng vào đồng đội của bạn, và chúng ta sẽ đạt được chiến thắng!\",             \"Đừng lo lắng, tôi sẽ đưa đội quân của chúng ta qua được những trận đánh khốc liệt nhất.\",             \"Sức mạnh của chúng ta sẽ khiến kẻ thù sợ hãi và chúng ta sẽ chiến thắng trong cuộc đối đầu này!\",             \"Làm sao để chiến thắng? Tập trung vào mục tiêu và sử dụng tất cả mọi thứ có thể để đánh bại đối thủ.\",             \"Hãy giữ bình tĩnh trong mọi tình huống để có thể đưa ra quyết định đúng đắn.\",             \"Trong cuộc chiến này, chỉ có sự kiên trì và nỗ lực vô tận mới là chìa khóa thành công.\"]','[   \"Nhận quà trùng sinh\",   \"Nhận quà chưa trùng sinh\",   \"Nhận quà sự kiện\",   \"Nhận quà top bang\" ]','[25,26,27,28]',81,342,'npcs/quan_ly.png',1,'[-25,-25,50,50]'),(-7,'BAC SI XI TIN','[\"Bác sĩ thú y mát tay đây (B)\"]','[   \"Hồi sinh pet sau PK\",   \"Nhận nhiệm vụ hằng ngày\",   \"Tẩy gym\" ]','[22,23,24]',470,344,'npcs/bac_si_xi_tin.png',1,'[-25,-25,50,50]'),(-6,'THO SAN','[\"Các bạn hãy cẩn thận khi tiếp cận những con thú hoang dã. Chúng có thể rất nguy hiểm đấy.\",             \"Tôi luôn phải cẩn thận để không bị những con thú hoang dã tấn công. Nhưng cũng vì thế mà tôi có thể kiếm được nhiều tiền đấy.\",             \"Trong việc săn bắn, sự kiên nhẫn là yếu tố quan trọng để thành công. Hãy chờ đợi và chỉ bắn vào khoảng thời gian thích hợp.\",             \"Cuộc sống trên thảo nguyên có vẻ đơn giản nhưng không hề dễ dàng. Tôi đã phải trải qua nhiều khó khăn để trở thành một thợ săn giỏi như hiện tại.\",             \"Mỗi loài động vật có cách thức di chuyển, cách sống và thậm chí cả thói quen. Nếu bạn muốn trở thành thợ săn giỏi, hãy tìm hiểu kỹ về chúng.\",             \"Sự tỉnh táo và nhạy bén là đặc điểm của một thợ săn giỏi. Khi bạn đi săn, hãy luôn đứng trên cảnh giác.\",             \"Để bắn chính xác, bạn cần phải có kinh nghiệm và tập trung tuyệt đối. Hãy luyện tập mỗi ngày để trở thành một thợ săn giỏi nhất.\",             \"Những con thú hoang dã rất thông minh và có khả năng tự vệ cao. Đừng chủ quan, hãy chuẩn bị tốt trước khi tiếp cận chúng.\",             \"Sau mỗi chuyến săn, bạn nên kiểm tra lại trang bị và vũ khí để sẵn sàng cho chuyến săn tiếp theo.\"]','[\"Ghép ngọc nguyên tố\",\"Bảng Anh Hùng\"]','[21,69]',310,500,'npcs/sat_thu.png',1,'[-25,-25,50,50]'),(-5,'THUONG NHAN','[\"Chào đón bạn đến với gian hàng của tôi, tôi có mọi thứ bạn cần cho chuyến phiêu lưu tiếp theo của bạn.\",             \"Bạn đang tìm kiếm một chiếc vũ khí mới? Hãy để tôi giúp bạn tìm thấy một cái phù hợp với phong cách của bạn.\",             \"Tôi luôn cập nhật các sản phẩm mới nhất và độc đáo nhất để đáp ứng nhu cầu của khách hàng.\",             \"Hãy mua sắm thả ga, không được để bỏ lỡ bất kỳ điều gì trong gian hàng của tôi đâu!\",             \"Bạn muốn cập nhật lại trang bị của mình? Hãy để tôi tư vấn cho bạn những chiếc áo giáp mạnh mẽ nhất.\",             \"Các vật phẩm huyền thoại và hiếm có đang chờ đón bạn tại gian hàng của tôi.\",             \"Khám phá những vật phẩm tuyệt vời từ khắp nơi trên thế giới để làm giàu và nâng cao sức mạnh cho thú cưng của bạn.\",             \"Tôi hy vọng bạn sẽ tìm thấy điều gì đó thú vị trong cửa hàng của tôi, và hãy trở lại khi bạn cần mua sắm thêm.\",             \"Chúc mừng nếu bạn mới bắt đầu chơi Gopet! Tôi có các mặt hàng cho người chơi mới để giúp bạn bắt đầu.\",             \"Tôi tự hào về sự đa dạng của sản phẩm tại cửa hàng của tôi. Hãy xem thử và tìm cho mình một món đồ ưa thích nhé!\"]','[   \"Mua đồ nâng cấp và xóa xăm\" ]','[20]',249,283,'npcs/thuong-nhan.png',1,'[-25,-25,50,50]'),(-4,'DU CON','[ \"Tôi thích tìm kiếm những pet hiếm để thay đổi trang phục cho chúng. Đó là một trong những thú vui của tôi khi chơi Gopet.\",\r\n            \"Các pet mới thường sẽ có kỹ năng đặc biệt, đó là lý do tại sao tôi luôn đổi trang bị để tận dụng tối đa khả năng của chúng.\",\r\n            \"Hình xăm trên cơ thể tôi minh chứng cho tình yêu của tôi với các pet trong Gopet.\",\r\n            \"Không chỉ là việc đánh bại kẻ địch, mà còn là sự hài lòng khi sở hữu pet quý hiếm, đó là nguồn động lực để tôi tiếp tục chiến đấu trong game.\",\r\n            \"Lúc này, tôi muốn đổi pet để áp dụng kỹ năng mới được học từ một con pet khác.\",\r\n            \"Mỗi pet trong Gopet đều có tính cách riêng, tôi muốn tìm ra sự kết hợp hoàn hảo giữa các pet để chiến đấu hiệu quả nhất.\",\r\n            \"Tôi không chỉ chơi Gopet để giải trí, mà còn để kết bạn với những người có sở thích giống tôi và cùng nhau chinh phục thế giới trong game.\",\r\n            \"Sự thay đổi pet và trang bị là cần thiết để đối mặt với các thử thách khác nhau trong game.\"]','[\"Đổi pet\",\"Xăm pet\",\"Xóa xăm pet\",\"Đổi cánh\",\"Đổi trang bị\",\"Top đại gia xuống núi\",\"Nhận nhiệm vụ sự kiện\",\"Tất cả xăm pet\"]','[15,16,17,18,19,59,68,70]',55,525,'npcs/Du_Con.png',1,'[-25,-25,50,50]'),(-3,'DAU TRUONG','[\"Đấu trường sôi động\"]','[\"Pet League Beta\",\"Chọn pet phòng thủ\",\"Vượt ải\",\"Shop đấu trường\",\"Shop đấu trường sinh tử\",\"Thách đấu\",\"Mua bình năng lượng\",\"Top điểm tích lũy\",\"Báo danh đấu trường\",\"Top vượt ải\"]','[64,65,10,11,12,13,14,63,67,80]',206,240,'npcs/arena.png',0,'[-25,-25,50,50]'),(-2,'TIEN NU','[\"Nhanh tay đánh quái đổi quà nè\",\"Phải 3 thỏi vàng mới đổi được đó nhé\",\"Phải 3 thỏi bạc mới đổi được đó nhé\"]','[\"Đổi phần thưởng\",\"Vật phẩm hiện có\",\"Tiến hóa pet\",\"Nâng sao pet\",\"Trùng sinh pet\",\"Danh hiệu của bạn\",\"Sử dụng danh hiệu\"]','[5,6,7,8,9,71,77]',386,133,'npcs/Tien_Nu.png',1,'[-25,-25,50,50]'),(-1,'TRAN CHAN','[\"Nhận pet miễn phí cho người mới :)\",\"Nhận pet miễn phí tại đây\"]','[\"Nhận pet miễn phí\",\"Shop Pet\",\"Top Pet\",\"Top Đại Gia\",\"Top Phú Hộ\",\"Nhập mã quà tặng\", \"Gộp đồ server cũ\",\"Bỏ thú cưng\"]','[1,2,3,4,41,60,81,98]',374,117,'npcs\\\\tran_tran.png',1,'[-25,-25,50,50]');
