-- 
-- Definition of gopet_pet
-- 

DROP TABLE IF EXISTS `gopet_pet`;
CREATE TABLE IF NOT EXISTS `gopet_pet` (
  `petId` int(11) NOT NULL,
  `name` varchar(200) DEFAULT NULL COMMENT 'Tên',
  `icon` text DEFAULT NULL,
  `frameImg` text DEFAULT NULL,
  `frameNum` int(11) NOT NULL DEFAULT 2,
  `vY` int(11) NOT NULL DEFAULT 0,
  `hp` int(11) NOT NULL DEFAULT 0 COMMENT 'Máu',
  `mp` int(11) NOT NULL DEFAULT 0 COMMENT 'Năng lượng',
  `str` int(11) DEFAULT NULL COMMENT 'Sức mạnh',
  `_int` int(11) DEFAULT NULL COMMENT 'Thông minh',
  `agi` int(11) DEFAULT NULL COMMENT 'Tốc độ',
  `type` int(11) NOT NULL DEFAULT 0 COMMENT 'Loại',
  `nclass` int(11) NOT NULL DEFAULT 0 COMMENT 'Phái',
  `element` int(11) NOT NULL DEFAULT 0 COMMENT 'Hệ',
  `gymUpLevel` int(11) NOT NULL DEFAULT 3,
  `FusionScore` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`petId`) USING BTREE,
  KEY `element` (`element`) USING BTREE,
  KEY `nclass` (`nclass`) USING BTREE,
  CONSTRAINT `gopet_pet_ibfk_1` FOREIGN KEY (`element`) REFERENCES `pet_element` (`elementId`),
  CONSTRAINT `gopet_pet_ibfk_2` FOREIGN KEY (`nclass`) REFERENCES `pet_class` (`classId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

