DROP TABLE IF EXISTS `task`;
CREATE TABLE IF NOT EXISTS `task` (
  `taskId` int(11) NOT NULL AUTO_INCREMENT,
  `type` int(11) NOT NULL,
  `name` text NOT NULL,
  `description` text NOT NULL,
  `guide` text DEFAULT NULL,
  `task` varchar(1000) NOT NULL DEFAULT '[]',
  `gift` varchar(1000) NOT NULL DEFAULT '[]',
  `fromNPC` int(11) NOT NULL,
  `taskNeed` varchar(5000) NOT NULL DEFAULT '[]',
  PRIMARY KEY (`taskId`) USING BTREE,
  KEY `taskID` (`taskId`) USING BTREE,
  KEY `fromNPC` (`fromNPC`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  CONSTRAINT `task_ibfk_1` FOREIGN KEY (`fromNPC`) REFERENCES `npc` (`npcId`),
  CONSTRAINT `task_ibfk_2` FOREIGN KEY (`type`) REFERENCES `task_type` (`taskType`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

