-- 
-- Definition of player
-- 

DROP TABLE IF EXISTS `player`;
CREATE TABLE IF NOT EXISTS `player` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `isAdmin` tinyint(1) NOT NULL DEFAULT 0,
  `name` text NOT NULL COMMENT 'Tên ',
  `gender` int(11) NOT NULL COMMENT 'Giới tính',
  `gold` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Vàng',
  `spendGold` bigint(20) NOT NULL DEFAULT 0,
  `coin` bigint(20) NOT NULL DEFAULT 50000 COMMENT 'Ngọc',
  `lua` bigint(20) NOT NULL DEFAULT 0 COMMENT 'Lúa',
  `items` longtext DEFAULT NULL COMMENT 'Hành trang',
  `favouriteList` longtext DEFAULT NULL COMMENT 'Danh sách bạn thân',
  `pets` longtext DEFAULT NULL,
  `petSelected` longtext DEFAULT NULL,
  `isFirstFree` tinyint(1) NOT NULL DEFAULT 0,
  `loginDate` datetime NOT NULL DEFAULT current_timestamp(),
  `star` int(11) NOT NULL DEFAULT 10,
  `skin` text DEFAULT NULL,
  `wing` text DEFAULT NULL,
  `isOnSky` tinyint(1) NOT NULL DEFAULT 0,
  `buffExp` text DEFAULT NULL,
  `pkPoint` int(11) NOT NULL DEFAULT 0,
  `pkPointTime` datetime NOT NULL DEFAULT current_timestamp(),
  `captcha` longtext DEFAULT NULL,
  `shopArena` varchar(4000) DEFAULT NULL,
  `clanId` int(11) NOT NULL DEFAULT -1,
  `tasking` longtext DEFAULT NULL,
  `task` longtext DEFAULT NULL,
  `wasTask` text DEFAULT NULL,
  `avatarPath` varchar(1000) NOT NULL DEFAULT 'npcs/gopet.png',
  `numUseEnergy` varchar(1100) NOT NULL DEFAULT '{}',
  `AccumulatedPoint` int(11) NOT NULL DEFAULT 0,
  `PetDefLeague` longtext DEFAULT NULL,
  `ArenaPoint` int(11) NOT NULL DEFAULT 0,
  `EventPoint` int(11) NOT NULL DEFAULT 0,
  `achievements` longtext NOT NULL,
  `NumOfUseKiteNormal` int(11) NOT NULL DEFAULT 0,
  `NumOfUseKiteVip` int(11) NOT NULL DEFAULT 0,
  `CurrentAchievementId` int(11) NOT NULL DEFAULT -1,
  `letters` longtext NOT NULL,
  `RequestAddFriends` longtext NOT NULL,
  `BlockFriendLists` longtext NOT NULL,
  `ListFriends` longtext NOT NULL,
  `LastTimeOnline` datetime NOT NULL DEFAULT current_timestamp(),
  `LettersSendTime` longtext NOT NULL,
  `MoneyDisplays` longtext NOT NULL,
  `KioskFund` int(11) NOT NULL DEFAULT 0,
  `TrashItemBackup` longtext NOT NULL,
  `ClanTasked` mediumtext NOT NULL,
  `TimeDropCoin` datetime NOT NULL DEFAULT current_timestamp(),
  `IsMergeServer` tinyint(4) NOT NULL DEFAULT 1,
  `NumGiveFlowerGold` int(11) NOT NULL DEFAULT 0,
  `NumGiveFlowerGem` int(11) NOT NULL DEFAULT 0,
  `IndexMilistoneTeacherEvent` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `FlowerGold` int(11) NOT NULL DEFAULT -1,
  `FlowerCoin` int(11) NOT NULL DEFAULT -1,
  `DailyNoelTime` datetime DEFAULT NULL,
  `DailyNoelIndex` tinyint(4) NOT NULL DEFAULT 0,
  `NumEatSquareStickyRice` int(11) NOT NULL DEFAULT 0,
  `NumEatSquareStickyRiceCoin` int(11) NOT NULL DEFAULT 0,
  `NumEatCylindricalStickyRice` int(11) NOT NULL DEFAULT 0,
  `NumEatCylindricalStickyRiceCoin` int(11) NOT NULL DEFAULT 0,
  `IndexMilistoneBirthdayEvent` tinyint(4) NOT NULL DEFAULT -1,
  `NumUseGiftBox2025` int(11) NOT NULL DEFAULT 0,
  `NapMocClaimed` bigint(20) NOT NULL DEFAULT 0,
  `NumBossFlowerCoin2026` int(11) NOT NULL DEFAULT 0,
  `NumUseMoonCakeBoxNormal2026` int(11) NOT NULL DEFAULT 0,
  `NumUseMoonCakeBoxVip2026` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `user_id_2` (`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=546 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC COMMENT='Dữ liệu của người chơi';

